import{_ as o,c as a,o as s,j as i,Y as n,t as r}from"./chunks/framework.D-NV0Bun.js";const m=JSON.parse('{"title":"git-receive-pack | x-cmd man (git man1) | Receive what is pushed into the repository","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-receive-pack - Receive what is pushed into the repository","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-receive-pack | x-cmd man (git man1) | Receive what is pushed into the repository"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-receive-pack - Receive what is pushed into the repository"}]]},"headers":[],"params":{"isMan":true,"man":"git-receive-pack","category":"git man1","desc":"Receive what is pushed into the repository"},"relativePath":"git/man1/git-receive-pack.md","filePath":"git/man1/[man].md"}'),h={name:"git/man1/git-receive-pack.md"},p={class:"visually-hidden"};function d(t,e,c,l,u,g){return s(),a("div",null,[i("h1",p,r(t.$params.man),1),e[0]||(e[0]=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-receive-pack - Receive what is pushed into the repository</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> receive-pack</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">git-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Invoked by <em>git send-pack</em> and updates the repository with the information fed from the remote end.</p><p>This command is usually not invoked directly by the end user. The UI for the protocol is on the <em>git send-pack</em> side, and the program pair is meant to be used to push updates to remote repository. For pull operations, see <strong>git-fetch-pack</strong>(1).</p><p>The command allows for creation and fast-forwarding of sha1 refs (heads/tags) on the remote end (strictly speaking, it is the local end <em>git-receive-pack</em> runs, but to the user who is sitting at the send-pack end, it is updating the remote. Confused?)</p><p>There are other real-world examples of using update and post-update hooks found in the Documentation/howto directory.</p><p><em>git-receive-pack</em> honours the receive.denyNonFastForwards config option, which tells it if updates to a ref should be denied if they are not fast-forwards.</p><p>A number of other receive.* config options are available to tweak its behavior, see <strong>git-config</strong>(1).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>&lt;git-dir&gt;</p><blockquote><p>The repository to sync into.</p></blockquote><p>--http-backend-info-refs</p><blockquote><p>Used by <strong>git-http-backend</strong>(1) to serve up <strong>$GIT_URL/info/refs?service=git-receive-pack</strong> requests. See <strong>--http-backend-info-refs</strong> in <strong>git-upload-pack</strong>(1).</p></blockquote><h2 id="pre-receive-hook" tabindex="-1">PRE-RECEIVE HOOK <a class="header-anchor" href="#pre-receive-hook" aria-label="Permalink to &quot;PRE-RECEIVE HOOK&quot;">​</a></h2><p>Before any ref is updated, if $GIT_DIR/hooks/pre-receive file exists and is executable, it will be invoked once with no parameters. The standard input of the hook will be one line per ref to be updated:</p><blockquote><pre><code>sha1-old SP sha1-new SP refname LF
</code></pre></blockquote><p>The refname value is relative to $GIT_DIR; e.g. for the master head this is &quot;refs/heads/master&quot;. The two sha1 values before each refname are the object names for the refname before and after the update. Refs to be created will have sha1-old equal to 0{40}, while refs to be deleted will have sha1-new equal to 0{40}, otherwise sha1-old and sha1-new should be valid objects in the repository.</p><p>When accepting a signed push (see <strong>git-push</strong>(1)), the signed push certificate is stored in a blob and an environment variable <strong>GIT_PUSH_CERT</strong> can be consulted for its object name. See the description of <strong>post-receive</strong> hook for an example. In addition, the certificate is verified using GPG and the result is exported with the following environment variables:</p><p><strong>GIT_PUSH_CERT_SIGNER</strong></p><blockquote><p>The name and the e-mail address of the owner of the key that signed the push certificate.</p></blockquote><p><strong>GIT_PUSH_CERT_KEY</strong></p><blockquote><p>The GPG key ID of the key that signed the push certificate.</p></blockquote><p><strong>GIT_PUSH_CERT_STATUS</strong></p><blockquote><p>The status of GPG verification of the push certificate, using the same mnemonic as used in <strong>%G?</strong> format of <strong>git log</strong> family of commands (see <strong>git-log</strong>(1)).</p></blockquote><p><strong>GIT_PUSH_CERT_NONCE</strong></p><blockquote><p>The nonce string the process asked the signer to include in the push certificate. If this does not match the value recorded on the &quot;nonce&quot; header in the push certificate, it may indicate that the certificate is a valid one that is being replayed from a separate &quot;git push&quot; session.</p></blockquote><p><strong>GIT_PUSH_CERT_NONCE_STATUS</strong></p><blockquote><p><strong>UNSOLICITED</strong></p><blockquote><p>&quot;git push --signed&quot; sent a nonce when we did not ask it to send one.</p></blockquote><p><strong>MISSING</strong></p><blockquote><p>&quot;git push --signed&quot; did not send any nonce header.</p></blockquote><p><strong>BAD</strong></p><blockquote><p>&quot;git push --signed&quot; sent a bogus nonce.</p></blockquote><p><strong>OK</strong></p><blockquote><p>&quot;git push --signed&quot; sent the nonce we asked it to send.</p></blockquote><p><strong>SLOP</strong></p><blockquote><p>&quot;git push --signed&quot; sent a nonce different from what we asked it to send now, but in a previous session. See <strong>GIT_PUSH_CERT_NONCE_SLOP</strong> environment variable.</p></blockquote></blockquote><p><strong>GIT_PUSH_CERT_NONCE_SLOP</strong></p><blockquote><p>&quot;git push --signed&quot; sent a nonce different from what we asked it to send now, but in a different session whose starting time is different by this many seconds from the current session. Only meaningful when <strong>GIT_PUSH_CERT_NONCE_STATUS</strong> says <strong>SLOP</strong>. Also read about <strong>receive.certNonceSlop</strong> variable in <strong>git-config</strong>(1).</p></blockquote><p>This hook is called before any refname is updated and before any fast-forward checks are performed.</p><p>If the pre-receive hook exits with a non-zero exit status no updates will be performed, and the update, post-receive and post-update hooks will not be invoked either. This can be useful to quickly bail out if the update is not to be supported.</p><p>See the notes on the quarantine environment below.</p><h2 id="update-hook" tabindex="-1">UPDATE HOOK <a class="header-anchor" href="#update-hook" aria-label="Permalink to &quot;UPDATE HOOK&quot;">​</a></h2><p>Before each ref is updated, if $GIT_DIR/hooks/update file exists and is executable, it is invoked once per ref, with three parameters:</p><blockquote><pre><code>$GIT_DIR/hooks/update refname sha1-old sha1-new
</code></pre></blockquote><p>The refname parameter is relative to $GIT_DIR; e.g. for the master head this is &quot;refs/heads/master&quot;. The two sha1 arguments are the object names for the refname before and after the update. Note that the hook is called before the refname is updated, so either sha1-old is 0{40} (meaning there is no such ref yet), or it should match what is recorded in refname.</p><p>The hook should exit with non-zero status if it wants to disallow updating the named ref. Otherwise it should exit with zero.</p><p>Successful execution (a zero exit status) of this hook does not ensure the ref will actually be updated, it is only a prerequisite. As such it is not a good idea to send notices (e.g. email) from this hook. Consider using the post-receive hook instead.</p><h2 id="post-receive-hook" tabindex="-1">POST-RECEIVE HOOK <a class="header-anchor" href="#post-receive-hook" aria-label="Permalink to &quot;POST-RECEIVE HOOK&quot;">​</a></h2><p>After all refs were updated (or attempted to be updated), if any ref update was successful, and if $GIT_DIR/hooks/post-receive file exists and is executable, it will be invoked once with no parameters. The standard input of the hook will be one line for each successfully updated ref:</p><blockquote><pre><code>sha1-old SP sha1-new SP refname LF
</code></pre></blockquote><p>The refname value is relative to $GIT_DIR; e.g. for the master head this is &quot;refs/heads/master&quot;. The two sha1 values before each refname are the object names for the refname before and after the update. Refs that were created will have sha1-old equal to 0{40}, while refs that were deleted will have sha1-new equal to 0{40}, otherwise sha1-old and sha1-new should be valid objects in the repository.</p><p>The *<em>GIT_PUSH_CERT*</em> * environment variables can be inspected, just as in <strong>pre-receive</strong> hook, after accepting a signed push.</p><p>Using this hook, it is easy to generate mails describing the updates to the repository. This example script sends one mail message per ref listing the commits pushed to the repository, and logs the push certificates of signed pushes with good signatures to a logger service:</p><blockquote><pre><code>#!/bin/sh
# mail out commit update information.
while read oval nval ref
do
        if expr &quot;$oval&quot; : &#39;0*$&#39; &gt;/dev/null
        then
                echo &quot;Created a new ref, with the following commits:&quot;
                git rev-list --pretty &quot;$nval&quot;
        else
                echo &quot;New commits:&quot;
                git rev-list --pretty &quot;$nval&quot; &quot;^$oval&quot;
        fi |
        mail -s &quot;Changes to ref $ref&quot; commit-list@mydomain
done
# log signed push certificate, if any
if test -n &quot;\${GIT_PUSH_CERT-}&quot; &amp;&amp; test \${GIT_PUSH_CERT_STATUS} = G
then
        (
                echo expected nonce is \${GIT_PUSH_NONCE}
                git cat-file blob \${GIT_PUSH_CERT}
        ) | mail -s &quot;push certificate from $GIT_PUSH_CERT_SIGNER&quot; push-log@mydomain
fi
exit 0
</code></pre></blockquote><p>The exit code from this hook invocation is ignored, however a non-zero exit code will generate an error message.</p><p>Note that it is possible for refname to not have sha1-new when this hook runs. This can easily occur if another user modifies the ref after it was updated by <em>git-receive-pack</em>, but before the hook was able to evaluate it. It is recommended that hooks rely on sha1-new rather than the current value of refname.</p><h2 id="post-update-hook" tabindex="-1">POST-UPDATE HOOK <a class="header-anchor" href="#post-update-hook" aria-label="Permalink to &quot;POST-UPDATE HOOK&quot;">​</a></h2><p>After all other processing, if at least one ref was updated, and if $GIT_DIR/hooks/post-update file exists and is executable, then post-update will be called with the list of refs that have been updated. This can be used to implement any repository wide cleanup tasks.</p><p>The exit code from this hook invocation is ignored; the only thing left for <em>git-receive-pack</em> to do at that point is to exit itself anyway.</p><p>This hook can be used, for example, to run <strong>git update-server-info</strong> if the repository is packed and is served via a dumb transport.</p><blockquote><pre><code>#!/bin/sh
exec git update-server-info
</code></pre></blockquote><h2 id="quarantine-environment" tabindex="-1">QUARANTINE ENVIRONMENT <a class="header-anchor" href="#quarantine-environment" aria-label="Permalink to &quot;QUARANTINE ENVIRONMENT&quot;">​</a></h2><p>When <strong>receive-pack</strong> takes in objects, they are placed into a temporary &quot;quarantine&quot; directory within the <strong>$GIT_DIR/objects</strong> directory and migrated into the main object store only after the <strong>pre-receive</strong> hook has completed. If the push fails before then, the temporary directory is removed entirely.</p><p>This has a few user-visible effects and caveats:</p><blockquote><p>1.</p><p>Pushes which fail due to problems with the incoming pack, missing objects, or due to the <strong>pre-receive</strong> hook will not leave any on-disk data. This is usually helpful to prevent repeated failed pushes from filling up your disk, but can make debugging more challenging.</p></blockquote><blockquote><p>2.</p><p>Any objects created by the <strong>pre-receive</strong> hook will be created in the quarantine directory (and migrated only if it succeeds).</p></blockquote><blockquote><p>3.</p><p>The <strong>pre-receive</strong> hook MUST NOT update any refs to point to quarantined objects. Other programs accessing the repository will not be able to see the objects (and if the pre-receive hook fails, those refs would become corrupted). For safety, any ref updates from within <strong>pre-receive</strong> are automatically rejected.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-send-pack</strong>(1), <strong>gitnamespaces</strong>(7)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,66))])}const k=o(h,[["render",d]]);export{m as __pageData,k as default};
